B.byX={"\u0936\u094d\u092f\u093e\u092e \u0915\u093f\u0930\u093e\u0928\u093e \u0938\u094d\u091f\u094b\u0930 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":0,"\u0915\u093f\u0938\u093e\u0928 \u0916\u093e\u0926-\u092c\u0940\u091c \u092d\u0902\u0921\u093e\u0930 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":1,[u.jz]:2,[u.bw]:3,"\u0930\u093e\u0927\u093f\u0915\u093e \u0935\u0938\u094d\u0924\u094d\u0930 \u092d\u0902\u0921\u093e\u0930 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":4,"\u092c\u093e\u091f\u093e-\u0938\u094d\u091f\u093e\u0907\u0932 \u092b\u093c\u0941\u091f\u0935\u093f\u092f\u0930 \u0939\u093e\u0909\u0938 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":5,"\u0936\u0947\u0916\u093e\u0935\u091f\u0940 \u092b\u093c\u0930\u094d\u0928\u0940\u091a\u0930 \u092e\u093e\u0930\u094d\u091f (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":6,"\u092e\u0930\u0941\u0927\u0930 \u092b\u093c\u0942\u0921\u094d\u0938 \u092a\u094d\u0930\u093e. \u0932\u093f. (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":7,"\u0938\u094b\u0928\u0940 \u091c\u094d\u0935\u0947\u0932\u0930\u094d\u0938 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":8,"\u091c\u0940\u0935\u0928 \u092e\u0947\u0921\u093f\u0915\u0932 \u0938\u094d\u091f\u094b\u0930 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":9,"\u092e\u0930\u0941\u0927\u0930 \u092d\u094b\u091c\u0928\u093e\u0932\u092f (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":10,[u.g5]:11,"\u0936\u0930\u094d\u092e\u093e \u090f\u0902\u0921 \u090f\u0938\u094b\u0938\u093f\u090f\u091f\u094d\u0938 (\u0928\u092e\u0942\u0928\u093e)":12,"\u0906\u0926\u0930\u094d\u0936 \u0935\u093f\u0926\u094d\u092f\u093e \u092e\u0902\u0926\u093f\u0930 (\u0928\u092e\u0942\u0928\u093e / \u0921\u0947\u092e\u094b)":13,"\u0938\u0930\u0938\u094d\u0935\u0924\u0940 \u092c\u093e\u0932 \u0935\u093f\u0926\u094d\u092f\u093e \u092e\u0902\u0926\u093f\u0930, \u091c\u0938\u0930\u093e\u0938\u0930 (\u0932\u093e\u0907\u091f \u0921\u0947\u092e\u094b)":14,"\u0906\u0926\u0930\u094d\u0936 \u0935\u093f\u0926\u094d\u092f\u093e \u092e\u0902\u0926\u093f\u0930, \u0928\u094b\u0916\u093e (\u092c\u0947\u0938\u093f\u0915 \u0921\u0947\u092e\u094b)":15,"\u0935\u0930\u094d\u091a\u0938\u094d\u0935 \u092a\u092c\u094d\u0932\u093f\u0915 \u0938\u094d\u0915\u0942\u0932, \u092c\u0940\u0915\u093e\u0928\u0947\u0930 (\u092a\u094d\u0930\u094b \u0921\u0947\u092e\u094b)":16,"\u092a\u0941\u0930\u093e\u0928\u093e \u092c\u093e\u091c\u093c\u093e\u0930, \u0928\u094b\u0916\u093e, \u092c\u0940\u0915\u093e\u0928\u0947\u0930 (\u0930\u093e\u091c.)":17,"\u092e\u0941\u0916\u094d\u092f \u092c\u093e\u091c\u093c\u093e\u0930, \u0928\u094b\u0916\u093e, \u092c\u0940\u0915\u093e\u0928\u0947\u0930 (\u0930\u093e\u091c.) 334803":18,"\u0939\u093e\u0908\u0935\u0947 NH-89, \u0928\u094b\u0916\u093e, \u092c\u0940\u0915\u093e\u0928\u0947\u0930 (\u0930\u093e\u091c.)":19,"\u092c\u0938 \u0938\u094d\u091f\u0948\u0902\u0921 \u0915\u0947 \u0938\u093e\u092e\u0928\u0947, \u0928\u094b\u0916\u093e, \u092c\u0940\u0915\u093e\u0928\u0947\u0930 (\u0930\u093e\u091c.)":20,"\u0926\u0941\u0915\u093e\u0928 \u0928\u0902. 45, \u0915\u0943\u0937\u093f \u0909\u092a\u091c \u092e\u0902\u0921\u0940, \u0928\u094b\u0916\u093e":21,[u.cE]:22,"\u0936\u0928\u093f\u0935\u093e\u0930 \u0915\u094b \u0938\u0941\u092c\u0939 10 \u092c\u091c\u0947 \u0905\u092d\u093f\u092d\u093e\u0935\u0915-\u0936\u093f\u0915\u094d\u0937\u0915 \u092c\u0948\u0920\u0915 \u0939\u0948\u0964 \u0915\u0943\u092a\u092f\u093e \u0905\u0935\u0936\u094d\u092f \u092a\u0927\u093e\u0930\u0947\u0902\u0964":23,"\u0915\u0943\u092a\u092f\u093e \u0907\u0938 \u092e\u093e\u0939 \u0915\u0940 \u092b\u093c\u0940\u0938 10 \u0924\u093e\u0930\u0940\u0916\u093c \u0924\u0915 \u091c\u092e\u093e \u0915\u0930\u093e\u090f\u0901\u0964":24,"\u0905\u092d\u093f\u092d\u093e\u0935\u0915-\u0936\u093f\u0915\u094d\u0937\u0915 \u092c\u0948\u0920\u0915":25,"\u092b\u093c\u0940\u0938 \u091c\u092e\u093e \u0915\u0930\u0947\u0902":26,"\u0935\u093e\u0930\u094d\u0937\u093f\u0915 \u0916\u0947\u0932\u0915\u0942\u0926 \u092a\u094d\u0930\u0924\u093f\u092f\u094b\u0917\u093f\u0924\u093e":27,"\u0905\u0930\u094d\u0927\u0935\u093e\u0930\u094d\u0937\u093f\u0915 \u092a\u0930\u0940\u0915\u094d\u0937\u093e \u0936\u0941\u0930\u0942":28,"\u0936\u0940\u0924\u0915\u093e\u0932\u0940\u0928 \u0905\u0935\u0915\u093e\u0936":29,"\u0905\u0927\u094d\u092f\u093e\u092f 3 \u2014 \u092a\u094d\u0930\u0936\u094d\u0928\u093e\u0935\u0932\u0940 3.2 \u0915\u0947 \u0938\u092d\u0940 \u0938\u0935\u093e\u0932":30,"\u092a\u093e\u0920 5 \u0915\u093e \u0938\u093e\u0930 \u0905\u092a\u0928\u0940 \u0915\u0949\u092a\u0940 \u092e\u0947\u0902 \u0932\u093f\u0916\u0947\u0902":31,"\u0905\u0927\u094d\u092f\u093e\u092f 2 \u2014 \u0905\u092e\u094d\u0932, \u0915\u094d\u0937\u093e\u0930\u0915 \u090f\u0935\u0902 \u0932\u0935\u0923 \u0915\u0947 \u092a\u094d\u0930\u0936\u094d\u0928 1\u201310":32,"\u0935\u093f\u0926\u094d\u092f\u0941\u0924 \u0906\u0935\u0947\u0936 \u2014 \u0906\u0902\u0915\u093f\u0915 \u092a\u094d\u0930\u0936\u094d\u0928 5":33,"\u0915 \u0938\u0947 \u091c\u094d\u091e \u0924\u0915 \u0926\u094b \u092c\u093e\u0930 \u0932\u093f\u0916\u0947\u0902":34,"\u092c\u0938 \u0938\u0941\u092c\u0939 15 \u092e\u093f\u0928\u091f \u0926\u0947\u0930 \u0938\u0947 \u0906\u0924\u0940 \u0939\u0948":35,"\u0906\u0930\u093e\u092e \u0915\u0930\u093e\u092f\u093e, \u0905\u092d\u093f\u092d\u093e\u0935\u0915 \u0915\u094b \u0938\u0942\u091a\u0928\u093e \u0926\u0940":36,"\u0939\u0932\u094d\u0915\u093e \u092c\u0941\u0916\u093e\u0930":37,"\u092a\u0930\u093f\u0935\u093e\u0930 \u0926\u0942\u0938\u0930\u0947 \u0936\u0939\u0930 \u0917\u092f\u093e":38,"\u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u094b \u092a\u0938\u0902\u0926 \u0928\u0939\u0940\u0902 \u0906\u092f\u093e":39,"\u0938\u093e\u0907\u091c\u093c \u091b\u094b\u091f\u093e \u2014 \u092c\u0926\u0932\u0940":40,"\u090f\u0921\u0935\u093e\u0902\u0938 \u2014 \u0936\u093e\u0926\u0940 \u0915\u093e \u092b\u093c\u0930\u094d\u0928\u0940\u091a\u0930":41,"\u0918\u0930 \u092a\u0930 \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u2014 \u091f\u0947\u092e\u094d\u092a\u094b RJ07 GB 1122":42,"\u092c\u0915\u093e\u092f\u093e \u092d\u0941\u0917\u0924\u093e\u0928 \u2014 45 \u0926\u093f\u0928 \u092a\u0942\u0930\u0947":43,"\u0938\u0930\u094d\u0935\u093f\u0938 \u092c\u093f\u0932 \u0915\u093e \u092c\u0915\u093e\u092f\u093e":44,"\u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0932\u0947 \u0917\u090f \u0925\u0947":45,"\u091b\u093e\u0924\u094d\u0930\u0935\u0943\u0924\u094d\u0924\u093f \u0915\u0947 \u0932\u093f\u090f":46,"\u090f\u0921\u092e\u093f\u0936\u0928 \u091c\u093e\u0928\u0915\u093e\u0930\u0940":47,"\u0909\u0924\u094d\u0924\u0940\u0930\u094d\u0923":48,"\u0905\u091a\u094d\u091b\u093e":49,"\u0915\u0941\u091b \u0928\u0939\u0940\u0902":50,"\u0905\u0930\u094d\u0927\u0935\u093e\u0930\u094d\u0937\u093f\u0915 \u092a\u0930\u093f\u0923\u093e\u092e":51,"\u0928\u0939\u093e\u0928\u0947 \u0915\u093e \u0938\u093e\u092c\u0941\u0928":52,"\u092a\u0947\u0902\u091f-\u0936\u0930\u094d\u091f \u0915\u092a\u0921\u093c\u093e (\u092e\u0940\u091f\u0930)":53,"\u0921\u092c\u0932 \u092c\u0947\u0921 \u0936\u0940\u0936\u092e (\u092c\u0949\u0915\u094d\u0938 \u0938\u094d\u091f\u094b\u0930\u0947\u091c)":54,"\u0938\u094d\u091f\u0940\u0932 \u0905\u0932\u092e\u093e\u0930\u0940 \u0917\u094b\u0926\u0930\u0947\u091c-\u091f\u093e\u0907\u092a":55,"\u092e\u0942\u0902\u0917 \u0926\u093e\u0932 \u0928\u092e\u0915\u0940\u0928 1 \u0915\u093f\u0932\u094b":56,"\u092e\u0942\u0902\u0917 \u0926\u093e\u0932 + \u092a\u093e\u092a\u0921\u093c \u0938\u0948\u0902\u092a\u0932":57,"\u0938\u0930\u094d\u0935\u093f\u0938 \u091a\u093e\u0930\u094d\u091c (\u091c\u0928\u0930\u0932 \u0938\u0930\u094d\u0935\u093f\u0938)":58,"\u092b\u093c\u0948\u0915\u094d\u091f\u094d\u0930\u0940 \u0917\u094b\u0921\u093e\u0909\u0928 (\u0915\u091a\u094d\u091a\u093e \u092e\u093e\u0932)":59,"\u0917\u0948\u0938, \u092c\u093f\u091c\u0932\u0940, \u092e\u091c\u093c\u0926\u0942\u0930\u0940 \u20b912/\u092a\u0948\u0915":60,"\u092d\u0941\u091c\u093f\u092f\u093e 1000 \u092a\u0948\u0915/\u092e\u093e\u0939 \u2014 \u0921\u093f\u0938\u094d\u091f\u094d\u0930\u0940\u092c\u094d\u092f\u0942\u091f\u0930\u0936\u093f\u092a":61,"\u092a\u0941\u0930\u093e\u0928\u093e \u091f\u094d\u0930\u0948\u0915\u094d\u091f\u0930 \u090f\u0915\u094d\u0938\u091a\u0947\u0902\u091c + \u092f\u0941\u0935\u094b 265":62,"\u0938\u094d\u0935\u0930\u093e\u091c 744 FE + \u0930\u094b\u091f\u093e\u0935\u0947\u091f\u0930, \u092b\u093c\u093e\u0907\u0928\u0947\u0902\u0938 \u092a\u0930":63}
